import{_ as a,o as n,c as s,a0 as c}from"./chunks/framework.DCluYYrN.js";const _=JSON.parse('{"title":"Поддержка x86_64","description":"","frontmatter":{},"headers":[],"relativePath":"ru_RU/guide/x86_64-support.md","filePath":"ru_RU/guide/x86_64-support.md"}'),l={name:"ru_RU/guide/x86_64-support.md"};function o(t,e,i,r,p,d){return n(),s("div",null,[...e[0]||(e[0]=[c(`<h1 id="поддержка-x86-64" tabindex="-1">Поддержка x86_64 <a class="header-anchor" href="#поддержка-x86-64" aria-label="Permalink to &quot;Поддержка x86_64&quot;">​</a></h1><p>KernelSU полностью поддерживает архитектуру <code>x86_64</code>. Однако из-за недавних изменений безопасности в upstream kernel для интеграции KernelSU в современные ядра <code>x86_64</code> требуется дополнительная обработка, чтобы наш единый dispatcher системных вызовов работал корректно.</p><h2 id="почему-это-перестало-работать" tabindex="-1">Почему это перестало работать? <a class="header-anchor" href="#почему-это-перестало-работать" aria-label="Permalink to &quot;Почему это перестало работать?&quot;">​</a></h2><p>В более новых версиях ядра был добавлен <a href="https://git.kernel.org/pub/scm/linux/kernel/git/stable/linux.git/commit/?id=1e3ad78334a69b36e107232e337f9d693dcc9df2" target="_blank" rel="noreferrer">коммит</a>, усиливающий защиту syscall table. Это изменение преобразовало косвенные переходы в пути системных вызовов в серию прямых условных переходов.</p><p>Механизм <code>syscall_hook</code> в KernelSU опирается на изменение записей в syscall table, чтобы перенаправлять перехваченные системные вызовы в единый dispatcher. Поскольку новое hardening-изменение меняет путь системных вызовов, ядро игнорирует такие изменения syscall table. Если KernelSU попытается загрузиться и установить hook на syscall table без корректной обработки этого ограничения, он не сможет маршрутизировать вызовы и безопасно прервет инициализацию, чтобы избежать kernel panic.</p><h2 id="как-исправить" tabindex="-1">Как исправить? <a class="header-anchor" href="#как-исправить" aria-label="Permalink to &quot;Как исправить?&quot;">​</a></h2><p>Есть два поддерживаемых способа решить проблему syscall hook на <code>x86_64</code>:</p><ol><li>Включить опцию сборки ядра <code>KSU_X86_PATCH_SYSCALL_DISPATCHER</code>.</li><li>Продолжить использовать исходный способ с патчами исходного кода ядра.</li></ol><p>Нужно выбрать только один из них. Не применяйте оба варианта одновременно.</p><h3 id="вариант-1-включить-ksu-x86-patch-syscall-dispatcher" tabindex="-1">Вариант 1: включить <code>KSU_X86_PATCH_SYSCALL_DISPATCHER</code> <a class="header-anchor" href="#вариант-1-включить-ksu-x86-patch-syscall-dispatcher" aria-label="Permalink to &quot;Вариант 1: включить \`KSU_X86_PATCH_SYSCALL_DISPATCHER\`&quot;">​</a></h3><p>В KernelSU 3.3.0 был добавлен новый официальный механизм для <code>x86_64</code>: опция сборки <code>KSU_X86_PATCH_SYSCALL_DISPATCHER</code>.</p><p>Когда эта опция включена, KernelSU динамически патчит hardened dispatcher системных вызовов во время выполнения, чтобы syscall hook работал без прежнего набора патчей исходного кода ядра. Это рекомендуемый вариант, если вы собираете ядро с KernelSU 3.3.0 или новее.</p><h3 id="вариант-2-применить-исходные-патчи-к-исходному-коду-ядра" tabindex="-1">Вариант 2: применить исходные патчи к исходному коду ядра <a class="header-anchor" href="#вариант-2-применить-исходные-патчи-к-исходному-коду-ядра" aria-label="Permalink to &quot;Вариант 2: применить исходные патчи к исходному коду ядра&quot;">​</a></h3><p>Если вы не хотите включать <code>KSU_X86_PATCH_SYSCALL_DISPATCHER</code>, можно продолжить использовать прежний подход с патчами ядра.</p><p>Чтобы KernelSU работал на этих более новых ядрах, примените патчи, которые позволяют обойти именно это syscall hardening.</p><div class="danger custom-block"><p class="custom-block-title">ПРЕДУПРЕЖДЕНИЕ О БЕЗОПАСНОСТИ</p><p>Используя любой из этих двух способов, вы намеренно обходите или ослабляете механизм защиты, предназначенный для снижения риска уязвимостей speculative execution.</p><p>Это снова открывает поверхность атаки через косвенные переходы для системных вызовов. <strong>Не используйте ни один из этих способов, если вы используете production-сервер или систему, где критична строгая защита от side-channel атак.</strong> Эти варианты предназначены для тестовых окружений, где root-доступ через KernelSU важнее данной конкретной аппаратной mitigation.</p></div><p>Выберите и примените патчи, соответствующие вашей версии ядра. Эти патчи создают возможность <code>X86_FEATURE_INDIRECT_SAFE</code>, которую можно активировать через параметр командной строки ядра <code>syscall_hardening=off</code>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>For kernel 6.6:</span></span>
<span class="line"><span>https://github.com/android-generic/kernel_common/commit/fe9a9b4c320577c30e1f22d04039e414c6a3cdec</span></span>
<span class="line"><span>https://github.com/android-generic/kernel_common/commit/df772e99e392f24b395ceaf7b26974e3e4828ee9</span></span>
<span class="line"><span></span></span>
<span class="line"><span>For kernel 6.12:</span></span>
<span class="line"><span>https://github.com/android-generic/kernel-zenith/commit/dd2c602268fdc81f4d3b662f6a15142ac0ec7bcd</span></span>
<span class="line"><span>https://github.com/android-generic/kernel-zenith/commit/7d99237ae5da61c19447138da3282ae37d43857b</span></span>
<span class="line"><span></span></span>
<span class="line"><span>For kernel 6.18:</span></span>
<span class="line"><span>https://github.com/android-generic/kernel-zenith/commit/40b1c323d1ad29c86e041d665c7f089b9a3ccfb5</span></span>
<span class="line"><span>https://github.com/android-generic/kernel-zenith/commit/f5813e10b7630e1ccd86fc2c4cf30eef60b64a82</span></span></code></pre></div><h2 id="какои-вариант-выбрать" tabindex="-1">Какой вариант выбрать? <a class="header-anchor" href="#какои-вариант-выбрать" aria-label="Permalink to &quot;Какой вариант выбрать?&quot;">​</a></h2><ul><li>Если вы используете KernelSU 3.3.0 или новее и можете изменить конфигурацию сборки KernelSU, включите <code>KSU_X86_PATCH_SYSCALL_DISPATCHER</code>.</li><li>Если вы хотите сохранить текущий workflow с патчами ядра, продолжайте использовать исходные патчи выше.</li></ul>`,20)])])}const u=a(l,[["render",o]]);export{_ as __pageData,u as default};
